// 添加开发调试信息 浏览器 - 开发者工具 - 审查元素 - 属性 - $_devInfo
export function addDevInfo(vueVm) {
  addGlobalToBody()
  // console.log(' ==== in addDevInfo ', vueVm)
  Promise.resolve().then(() => {
    let useVm = vueVm
    if (useVm?.config?.id) {
      let devInfo = {}
      if (useVm?.$el) {
        useVm.$el.$_devInfo = devInfo
      }
      if (useVm?.$el?.__vue__) {
        useVm.$el.__vue__.$_devInfo = devInfo
      }
      let selfNode = useVm.selfNode()
      // 节点上也添加调试信息
      if (selfNode) {
        selfNode.$_devInfo = devInfo
      }
      // 添加节点id
      devInfo.id = useVm?.config?.id
      // 添加节点$el方便选中
      Object.defineProperty(devInfo, '$el', {
        get() {
          if (useVm?.config?.id) {
            return window.tech_app.page.getNode(useVm.config.id)?.instance?.$el
          }
          return null
        }
      })
      // 添加节点信息
      Object.defineProperty(devInfo, 'node', {
        get() {
          if (useVm?.config?.id) {
            return window.tech_app.page.getNode(useVm.config.id)
          }
          return null
        }
      })
      // 添加节点数据信息
      Object.defineProperty(devInfo, 'data', {
        get() {
          if (useVm?.config?.id) {
            return window.tech_app.page.getNode(useVm.config.id)?.data
          }
          return null
        }
      })
      // 添加节点数据源信息
      Object.defineProperty(devInfo, 'ds_config', {
        get() {
          if (useVm?.config?.id) {
            return window.tech_app.page.getNode(useVm.config.id)?.data?.ds_config
          }
          return null
        }
      })
      // 添加节点实例信息
      Object.defineProperty(devInfo, 'instance', {
        get() {
          if (useVm?.config?.id) {
            return window.tech_app.page.getNode(useVm.config.id)?.instance
          }
          return null
        }
      })
      // 添加扩展信息
      Object.defineProperty(devInfo, 'extends', {
        get() {
          if (useVm?.config?.id) {
            return window.tech_app.extendViewTrace(useVm.config.id)
          }
          return null
        }
      })
      // 添加孩子items信息
      Object.defineProperty(devInfo, 'items', {
        get() {
          if (useVm?.config?.id) {
            let its = window.tech_app.page.getNode(useVm.config.id)?.data?.items || []
            return its.map((item) => {
              // return window.tech_app.page.getNode(item?.id)?.instance?.$el?.__vue__?.$_devInfo
              return window.tech_app.page.getNode(item?.id)?.$_devInfo
            })
          }
          return null
        }
      })
    }
  })
}
// 移除调试信息
export function removeDevInfo(vueVm) {
  if (vueVm?.$el?.$_devInfo) {
    vueVm.$el.$_devInfo = null
  }
  if (vueVm?.$el?.__vue__?.$_devInfo) {
    vueVm.$el.__vue__.$_devInfo = null
  }
  let selfNode = vueVm?.selfNode?.()
  if (selfNode) {
    selfNode.$_devInfo = null
    selfNode = null
  }
}

// 添加全局信息到body
const addGlobalToBody = () => {
  if (!Object.hasOwnProperty.call(document.body, '$_devInfo')) {
    document.body.$_devInfo = {}
    Object.defineProperty(document.body.$_devInfo, 'Tech', {
      get() {
        return window.Tech
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'loadedApps', {
      get() {
        return window.tech_apps_comps
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'loadedAppsSub', {
      get() {
        return window.tech_apps_comps_sub
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'devApps', {
      get() {
        return window.techDevApps
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'devAppsSub', {
      get() {
        return window.tech_apps_comps_sub
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'app', {
      get() {
        return window.tech_app
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'appsInfo', {
      get() {
        return window.tech_apps
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'blocks', {
      get() {
        return window.__blockComps
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'modelViews', {
      get() {
        return window.tech_model_views
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'Vue', {
      get() {
        return window.Vue
      }
    })
    Object.defineProperty(document.body.$_devInfo, 'options', {
      get() {
        return window.Vue.prototype.$paramOptions
      }
    })
  }
}

if (!window.Tech) {
  window.Tech = {}
}
// 放到全局方法里面
// 提供core里面的base-mixin.ts调用
window.Tech._addDevInfo = addDevInfo
// 提供core里面的base-mixin.ts调用
window.Tech._removeDevInfo = removeDevInfo
